func appU16(s string)*uint16{p,_:=syscall.UTF16PtrFromString(s);return p};func appSetText(h uintptr,s string){if h==0{return};p:=appU16(s);user32.NewProc("SetWindowTextW").Call(h,uintptr(unsafe.Pointer(p)))};func appSetEnabled(h uintptr,b bool){if h==0{return};v:=uintptr(0);if b{v=1};user32.NewProc("EnableWindow").Call(h,v)};func appMake(p uintptr,c,t string,st uint32,x,y,w,h int,id uintptr)uintptr{a,b:=appU16(c),appU16(t);v,_,_:=user32.NewProc("CreateWindowExW").Call(0,uintptr(unsafe.Pointer(a)),uintptr(unsafe.Pointer(b)),uintptr(st),uintptr(x),uintptr(y),uintptr(w),uintptr(h),p,id,appHInstance,0);return v}
