func appBuildControls(h uintptr){appOpenButton=appMake(h,"BUTTON","ABRIR EXCEL",WS_CHILD|WS_VISIBLE|WS_TABSTOP|BS_PUSHBUTTON,10,8,105,26,appIDOpen);appColumnsButton=appMake(h,"BUTTON","COLUMNAS",WS_CHILD|WS_VISIBLE|WS_TABSTOP|BS_PUSHBUTTON,120,8,90,26,appIDColumns);appConfigButton=appMake(h,"BUTTON","CONFIGURACIÓN",WS_CHILD|WS_VISIBLE|WS_TABSTOP|BS_PUSHBUTTON,215,8,120,26,appIDConfig);appStatus=appMake(h,"STATIC","Seleccione uno o varios archivos XLSX.",WS_CHILD|WS_VISIBLE,345,11,840,20,appIDStatus);appView=columnViewCreate(h)}
