func parseMultiBuffer(b []uint16)[]string{end:=0;for end+1<len(b){if b[end]==0&&b[end+1]==0{break};end++};if end==0{return nil};parts:=strings.Split(string(utf16.Decode(b[:end])),"\x00");if len(parts)==1{return []string{parts[0]}};out:=[]string{};dir:=parts[0];for _,p:=range parts[1:]{if p!=""{if !filepath.IsAbs(p){p=filepath.Join(dir,p)};out=append(out,p)}};return out}
func appPickXLSX(owner uintptr)[]string{a,_:=syscall.UTF16FromString("Archivos Excel (*.xlsx)");b,_:=syscall.UTF16FromString("*.xlsx");c,_:=syscall.UTF16FromString("Todos los archivos (*.*)");d,_:=syscall.UTF16FromString("*.*");f:=append(append(append(append([]uint16{},a...),b...),c...),d...);f=append(f,0,0);buf:=make([]uint16,32768);o:=appOpenFile{LStructSize:uint32(unsafe.Sizeof(appOpenFile{})),HwndOwner:owner,Filter:uintptr(unsafe.Pointer(&f[0])),FilterIndex:1,File:uintptr(unsafe.Pointer(&buf[0])),MaxFile:uint32(len(buf)),Title:uintptr(unsafe.Pointer(appU16("Seleccionar uno o varios archivos Excel"))),Flags:ofnExplorer|ofnFileMustExist|ofnPathMustExist|ofnHideReadOnly|ofnAllowMultiSelect|ofnNoChangeDir,DefExt:uintptr(unsafe.Pointer(appU16("xlsx")))};ret,_,_:=comdlg32.NewProc("GetOpenFileNameW").Call(uintptr(unsafe.Pointer(&o)));if ret==0{return nil};return parseMultiBuffer(buf)}
func appOpenXLSX(owner uintptr){paths:=appPickXLSX(owner);if len(paths)==0{return};appSetEnabled(appOpenButton,false);appSetText(appStatus,fmt.Sprintf("Leyendo %d Excel en segundo plano...",len(paths)));go func(){start:=time.Now();docs:=make([]*xlsxDoc,0,len(paths));var e error;for _,p:=range paths{var d *xlsxDoc;d,e=ReadXLSX(p);if e!=nil{break};decorateXLSXDates(d,p);docs=append(docs,d)};var ds *MemoryDataset;if e==nil{ds,e=BuildMemoryDataset(docs,appSettings);if e==nil{applyDatasetFormula(ds,appSettings);applySavedColumnVisibility(ds)}};appImportMu.Lock();appPendingDataset=ds;appPendingPaths=append([]string{},paths...);appPendingErr=e;appImportMu.Unlock();appLog("EVENTO: consolidacion finalizada; archivos=%d duración=%s",len(paths),time.Since(start));user32.NewProc("PostMessageW").Call(owner,WM_APP_IMPORT_DONE,0,0)}()}
func applySavedColumnVisibility(ds *MemoryDataset){if ds==nil||len(appSettings.VisibleColumns)==0{return};allowed:=map[string]bool{};for _,k:=range appSettings.VisibleColumns{allowed[k]=true};for i:=range ds.Columns{ds.Columns[i].Visible=allowed[datasetColumnKey(ds.Columns[i])]}}
func saveVisibleColumns(){if columnViewVisibleColumns()==nil{return};keys:=make([]string,0);for _,c:=range columnViewVisibleColumns(){keys=append(keys,datasetColumnKey(c))};appSettings.VisibleColumns=keys;_ = saveDatasetSettings(appSettings)}
func findChildByID(p uintptr,cls string,id uintptr)uintptr{c:=appU16(cls);prev:=uintptr(0);for i:=0;i<1000;i++{h,_,_:=user32.NewProc("FindWindowExW").Call(p,prev,uintptr(unsafe.Pointer(c)),0);if h==0{return 0};if h==prev{return 0};x,_,_:=user32.NewProc("GetDlgCtrlID").Call(h);if x==id{return h};prev=h};appLog("DIAGNOSTICO: findChildByID abortado por limite; parent=0x%X clase=%s id=%d",p,cls,id);return 0}
func appFinishImport(h uintptr){defer appRecover("appFinishImport");appLog("DIAGNOSTICO: appFinishImport IN");appImportMu.Lock();ds,paths,e:=appPendingDataset,appPendingPaths,appPendingErr;appPendingDataset=nil;appPendingPaths=nil;appPendingErr=nil;appImportMu.Unlock();openButton:=appOpenButton;if openButton==0{openButton=findChildByID(h,"BUTTON",appIDOpen)};appSetEnabled(openButton,true);if e!=nil{appSetText(appStatus,"ERROR al consolidar XLSX: "+e.Error());appLog("DIAGNOSTICO: appFinishImport error=%v",e);return};if ds==nil{appSetText(appStatus,"ERROR: la importación finalizó sin datos.");appLog("DIAGNOSTICO: appFinishImport abortado: dataset nil sin error");return};appImportedDataset=ds;appImportedPaths=paths;columnViewSetDatasetSafe(ds);appSetText(appStatus,fmt.Sprintf("EN MEMORIA: %d líneas | %d duplicadas SO+ITEM | %d enriquecidas por CSV | %d archivo(s)",len(ds.Records),ds.DuplicateSO,ds.Enriched,len(paths)));appLog("EVENTO: dataset en memoria; lineas=%d duplicadas_so_item=%d CSV=%d",len(ds.Records),ds.DuplicateSO,ds.Enriched)}
func appApplySettings(){if appImportedDataset!=nil{applyDatasetFormula(appImportedDataset,appSettings);columnViewSetDatasetSafe(appImportedDataset)}}
func workbookSize(doc *xlsxDoc)(rows,cells int){if doc==nil{return};for _,rs:=range doc.Sheets{rows+=len(rs);for _,r:=range rs{cells+=len(r)}};return}
func cleanCell(s string)string{return strings.NewReplacer("\r"," ","\n"," ","\t"," ").Replace(s)}
